import { buildStatementsApi } from "./api";

/**
 * `/statements` accepts `page[limit]` but ignores it, so every read of the
 * list costs a full unpaged response and routinely outruns jest's 60s default
 * — including for the single-statement suites, which have to resolve an id
 * through the list first.
 */
export const STATEMENTS_TIMEOUT_MS = 180_000;

/**
 * A statement id, or `null` when the org has none.
 *
 * Statements are generated by Unit at the close of each monthly period; there
 * is no operation to mint one. A freshly provisioned sandbox account therefore
 * has no statement at all, which makes the per-statement PDF / HTML reads
 * unreachable rather than broken.
 */
export async function getStatementId(): Promise<string | null> {
	const { data } = await buildStatementsApi().listStatements({
		pageLimit: "1",
	});
	const first = Array.isArray(data.data) ? data.data[0] : undefined;
	if (first && typeof first.id === "string") return first.id;
	console.warn(
		"This sandbox org has no statements (they are generated monthly and cannot be created from the API); skipping.",
	);
	return null;
}
